"""Наряд 6.2 (рядки 5982, 4684, 6075): речі моделі на фото сцени «оціни мій образ» стенда (`рв6_стенд.js`, `ОЦІНКА_ФІГУРИ`) — помилки
РОЗПІЗНАВАННЯ окремо від помилок АДРЕСУВАННЯ, на ЗАПИСАНИХ відповідях «ОЦІНКА: речі на фото» живих 14, 15, 22, 24, 25, 27. Правда —
фігури стенда в тисячних (ф2 — обидві форми ботильйонів, і `OTSINKA_F2=L`): ф1 — жакет, сорочка, спідниця; ф2 — дві пари взуття.
Рамка (≥ 25 % меншої з площ) на фігурі свого фото тієї ж родини слота — вірно; на фігурі іншого фото тієї ж родини й сім'ї кольору —
адресування (ід фото не той; так само річ, чий слот і колір має лише фігура іншого фото); на фігурі свого фото іншої родини — розпізнавання (ботильйон «верхом»); на фігурі іншого фото того ж
кольору, але іншої родини — адресування й розпізнавання; ні на чому — рамка мимо. Без рамки — за родиною слота й кольором фігур свого й іншого фото. Окремо: взуття ф2 зі слотом shoes (4684) і «низ» на ф2 (5982) за причиною.
Запуск: cd джерела && python3 -W ignore проби/реєстр_речей_6_2.py"""
import collections, re, subprocess, sys; sys.path.insert(0, "."); import оцінка_образу as О, verify as V
сім = lambda с: {"беж / кемел": "світла нейтраль"}.get(V.сім_я_слова(с), V.сім_я_слова(с)) if с else None   # беж ≈ вершковий
git = lambda *а: subprocess.run(["git", "-c", "core.quotepath=false", *а], capture_output=True, text=True).stdout
РОД = {"верх": "верх", "верхній_шар": "верх", "сукня": "верх", "низ": "низ", "взуття": "взуття"}
ПРАВДА = {"ф1": [("верх", "хакі", (200, 112, 800, 588)), ("верх", "блакитний", (417, 137, 583, 500)), ("низ", "бордовий", (283, 650, 717, 950))],
          "ф2": [("взуття", "вершковий", (117, 283, 450, 800)), ("взуття", "чорний", (550, 283, 883, 800))]}
def на(р, ф):      # (частка перекриття, родина, колір) фігури фото ф, на яку лягла рамка р, чи None
    кр = [(max(0, min(р[2], ц) - max(р[0], а)) * max(0, min(р[3], г) - max(р[1], б)) / min((р[2] - р[0]) * (р[3] - р[1]), (ц - а) * (г - б)), род, кол)
          for род, кол, (а, б, ц, г) in ПРАВДА[ф]] if р else []
    return max([х for х in кр if х[0] >= .25] or [None], key=lambda х: х[0] if х else 0)
к, низ, взуття = collections.Counter(), collections.Counter(), collections.Counter()
for г, т in {"1516-18": "1516_18/B"}.items():
    git("fetch", "-q", "--depth=1", "origin", "claude/zhyvi-%s:refs/remotes/origin/claude/zhyvi-%s" % (г, г))
    for ф in [ф for ф in git("ls-tree", "-r", "--name-only", "origin/claude/zhyvi-" + г, ":/аудит/живі_" + т).split("\n") if re.search(r"оціни_образ.*ОЦІНКА_речі_на_фото\.txt$", ф)]:
        відп = git("show", "origin/claude/zhyvi-%s:%s" % (г, ф)).split("── ВІДПОВІДЬ", 1)[-1].split("\n", 1)[-1]
        речі = О.речі_з_відповіді(відп, [{"ід": "ф1"}, {"ід": "ф2"}])["речі"]; к["викликів"] += 1; взуття["викликів"] += 1
        взуття["з взуттям ф2 (shoes)"] += any(р["фото"] == "ф2" and р["слот"] == "взуття" for р in речі)
        for р in речі:
            рамка = [р["рамка"][х] for х in ("ліво", "верх", "право", "низ")] if р.get("рамка") else None
            інше, рд = ("ф2" if р["фото"] == "ф1" else "ф1"), РОД.get(р["слот"])
            свій, чуже = на(рамка, р["фото"]), на(рамка, інше)
            if not рамка:      # без рамки — за родиною слота й кольором фігур фото
                свій = next(((1, рд, 0) for х in ПРАВДА[р["фото"]] if рд == х[0]), (1, None, 0))
                чуже = next(((1, рд, х[1]) for х in ПРАВДА[інше] if рд == х[0] and сім(р["колір"]) == сім(х[1])), None)
            той = чуже and сім(чуже[2]) == сім(р["колір"])      # рамка на фігурі іншого фото того самого кольору
            там = any(рд == х[0] and сім(х[1]) == сім(р["колір"]) for х in ПРАВДА[інше]) and not (свій and сім(свій[2]) == сім(р["колір"]))
            чому = "вірно" if свій and свій[1] == рд else "адресування" if (той and чуже[1] == рд) or там \
                else "розпізнавання" if свій else "адресування й розпізнавання" if той else "рамка мимо"
            к[чому] += 1
            if р["фото"] == "ф2" and р["слот"] == "низ": низ[чому] += 1; низ["викликів з «низом» ф2"] += 0
        низ["викликів з «низом» ф2"] += any(р["фото"] == "ф2" and р["слот"] == "низ" for р in речі)
for н, х in (("речі", к), ("«низ» на ф2", низ), ("взуття ф2", взуття)): print(н + ":", " · ".join("%s %d" % і for і in sorted(х.items())))
